fn contains(table: &[u64], hash: u64) -> bool {
    table.binary_search(&hash).is_ok()
}

fn pair(hash: u64, keep: &[u64], cull: &[u64]) -> Role {
    if contains(cull, hash) {
        Role::Cull
    } else if contains(keep, hash) {
        Role::Keep
    } else {
        Role::None
    }
}

pub(super) fn profile_role(profile: Profile, hash: u64) -> Role {
    match profile {
        Profile::KazuyaFSmash => pair(hash, &KAZUYAFSMASH_KEEP, &KAZUYAFSMASH_CULL),
        Profile::FalconPunch => pair(hash, &FALCONPUNCH_KEEP, &FALCONPUNCH_CULL),
        Profile::NessUpB => pair(hash, &NESSUPB_KEEP, &NESSUPB_CULL),
        Profile::LucasUpB => pair(hash, &LUCASUPB_KEEP, &LUCASUPB_CULL),
        Profile::IkeNeutralB => pair(hash, &IKENEUTRALB_KEEP, &IKENEUTRALB_CULL),
        Profile::ChromNeutralB => pair(hash, &CHROMNEUTRALB_KEEP, &CHROMNEUTRALB_CULL),
        Profile::RoyNeutralB => pair(hash, &ROYNEUTRALB_KEEP, &ROYNEUTRALB_CULL),
        Profile::PalutenaRapidJab => pair(hash, &PALUTENARAPIDJAB_KEEP, &PALUTENARAPIDJAB_CULL),
        Profile::PalutenaNeutralB => pair(hash, &PALUTENANEUTRALB_KEEP, &PALUTENANEUTRALB_CULL),
        Profile::PalutenaUpB => pair(hash, &PALUTENAUPB_KEEP, &PALUTENAUPB_CULL),
        Profile::PalutenaSideB => pair(hash, &PALUTENASIDEB_KEEP, &PALUTENASIDEB_CULL),
        Profile::PalutenaUpSmash => pair(hash, &PALUTENAUPSMASH_KEEP, &PALUTENAUPSMASH_CULL),
        Profile::PalutenaTilts => pair(hash, &PALUTENATILTS_KEEP, &PALUTENATILTS_CULL),
        Profile::PalutenaWingSmash => pair(hash, &PALUTENAWINGSMASH_KEEP, &PALUTENAWINGSMASH_CULL),
        Profile::PalutenaUpAir => pair(hash, &PALUTENAUPAIR_KEEP, &PALUTENAUPAIR_CULL),
        Profile::EdgeFSmash => pair(hash, &EDGEFSMASH_KEEP, &EDGEFSMASH_CULL),
        Profile::EdgePurpleDash => pair(hash, &EDGEPURPLEDASH_KEEP, &EDGEPURPLEDASH_CULL),
        Profile::EdgeNeutralB => pair(hash, &EDGENEUTRALB_KEEP, &EDGENEUTRALB_CULL),
        Profile::EdgeDownB => pair(hash, &EDGEDOWNB_KEEP, &EDGEDOWNB_CULL),
        Profile::EdgeSideB => pair(hash, &EDGESIDEB_KEEP, &EDGESIDEB_CULL),
    }
}

pub(super) fn global_role(hash: u64) -> Role {
    let found = [
        pair(hash, &PYRA_KEEP, &PYRA_CULL),
        pair(hash, &MYTHRA_KEEP, &MYTHRA_CULL),
        pair(hash, &BYLETH_KEEP, &BYLETH_CULL),
        pair(hash, &INKLING_KEEP, &INKLING_CULL),
        pair(hash, &GANONDORF_KEEP, &GANONDORF_CULL),
        pair(hash, &CHROMEXTRA_KEEP, &CHROMEXTRA_CULL),
    ];
    for role in found {
        if role != Role::None {
            return role;
        }
    }
    Role::None
}

pub(super) fn family_named(hash: u64) -> bool {
    const PROFILES: [Profile; 20] = [
        Profile::KazuyaFSmash,
        Profile::FalconPunch,
        Profile::NessUpB,
        Profile::LucasUpB,
        Profile::IkeNeutralB,
        Profile::ChromNeutralB,
        Profile::RoyNeutralB,
        Profile::PalutenaRapidJab,
        Profile::PalutenaNeutralB,
        Profile::PalutenaUpB,
        Profile::PalutenaSideB,
        Profile::PalutenaUpSmash,
        Profile::PalutenaTilts,
        Profile::PalutenaWingSmash,
        Profile::PalutenaUpAir,
        Profile::EdgeFSmash,
        Profile::EdgePurpleDash,
        Profile::EdgeNeutralB,
        Profile::EdgeDownB,
        Profile::EdgeSideB,
    ];
    PROFILES
        .iter()
        .any(|profile| profile_role(*profile, hash) != Role::None)
        || global_role(hash) != Role::None
}
